class Demo {
    static int test() {
        try {
            System.out.print("T");
            int z = 0;
            return 8 / z;
        } catch (ArithmeticException e) {
            System.out.print("C");
            return 4;
        } finally { System.out.print("F"); }
    }
}
System.out.print(Demo.test());

import java.io.IOException;
class Demo {
    static void read() throws IOException {
        throw new IOException();
    }
    static void run() {
        try { read(); }
        catch (RuntimeException e) { System.out.print("R"); }
        finally { System.out.print("F"); }
    }
}
